//! Raw bindings generated by `scripts/bindings.sh` from FFmpeg's
//! nv-codec-headers. Nothing here is safe to use directly; the rest of the
//! crate wraps it. Exposed for callers that need a constant or a struct the
//! safe layer does not cover yet, without any stability promise.
//!
//! Every function type is an `Option<unsafe extern "C" fn ..>` typedef for
//! runtime loading (see [`crate::loader`]); nothing links against the NVIDIA
//! libraries at build time. `CUDAAPI` / `NVENCAPI` are `__stdcall` on Windows,
//! which on the 64-bit targets this crate supports is the C calling
//! convention.

#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    missing_docs,
    unreachable_pub,
    clippy::all,
    clippy::pedantic,
    clippy::undocumented_unsafe_blocks,
    rustdoc::all,
    unnecessary_transmutes,
    clippy::allow_attributes_without_reason,
    reason = "generated by bindgen from the C headers; names and docs follow the headers"
)]
pub mod cuda;

#[allow(
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    missing_docs,
    unreachable_pub,
    clippy::all,
    clippy::pedantic,
    clippy::undocumented_unsafe_blocks,
    rustdoc::all,
    unnecessary_transmutes,
    reason = "generated by bindgen from the C headers; names and docs follow the headers"
)]
pub mod cuvid;

pub mod nvenc;
